INSERT INTO hoja(conjunto_id,orden,ejemplo_enunciado,ejemplo_resolucion) VALUES ((SELECT id FROM conjunto WHERE codigo='U3-C06'),1,'Si pintas 2/8 y luego 3/8 de una misma figura, sumas…','2/8 + 3/8 = 5/8. El denominador no cambia.') ON CONFLICT(conjunto_id,orden) DO UPDATE SET ejemplo_enunciado=EXCLUDED.ejemplo_enunciado,ejemplo_resolucion=EXCLUDED.ejemplo_resolucion;
